   "source": [
    "nlp_sim = spacy.load(\"fr_core_news_md\")\n",
    "mot_exemple_a = nlp_sim(\"rivière\")\n",
    "mot_exemple_b = nlp_sim(\"fleuve\")\n",
    "print(\"Vecteurs présents :\", mot_exemple_a.has_vector, mot_exemple_b.has_vector)\n",
    "print(\"rivière / fleuve :\", mot_exemple_a.similarity(mot_exemple_b))\n"
   ],
